/**
 * sync-skill-fallback.mjs — write the "no MCP? use the shell" fragment into every SLM skill.
 *
 * plugin-src/fragments/no-mcp-cli.md is the one copy. This writes it between
 * <!-- slm:no-mcp-cli:start --> and <!-- slm:no-mcp-cli:end --> in each
 * plugin-src/skills/<name>/SKILL.md (before the version footer, or at the end),
 * so every distribution built from plugin-src ships it. slm-cli is generated by
 * scripts/build_cli_skill.py, which writes the same fragment itself.
 *
 *   node scripts/sync-skill-fallback.mjs           # write
 *   node scripts/sync-skill-fallback.mjs --check   # exit 1 when a skill has drifted
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const FRAGMENT = path.join(ROOT, 'plugin-src', 'fragments', 'no-mcp-cli.md');
const SKILLS = path.join(ROOT, 'plugin-src', 'skills');
export const START = '<!-- slm:no-mcp-cli:start -->';
export const END = '<!-- slm:no-mcp-cli:end -->';
const GENERATED_ELSEWHERE = new Set(['slm-cli']);
const FOOTER = /\n---\n\n\*SuperLocalMemory v[^\n]*\*\n*$/;

export function block(fragment) {
  return `${START}\n${fragment.replace(/^\n+|\n+$/g, '')}\n${END}`;
}

export function withFragment(text, fragment) {
  const wanted = block(fragment);
  const start = text.indexOf(START);
  if (start !== -1) {
    const end = text.indexOf(END, start);
    if (end === -1) throw new Error(`unterminated ${START}`);
    return text.slice(0, start) + wanted + text.slice(end + END.length);
  }
  const footer = text.match(FOOTER);
  if (footer) {
    const at = footer.index;
    return `${text.slice(0, at).replace(/\n+$/, '')}\n\n${wanted}\n${text.slice(at)}`;
  }
  return `${text.replace(/\n+$/, '')}\n\n${wanted}\n`;
}

function main(argv) {
  const check = argv.includes('--check');
  const fragment = fs.readFileSync(FRAGMENT, 'utf8');
  const drifted = [];
  for (const name of fs.readdirSync(SKILLS).sort()) {
    if (GENERATED_ELSEWHERE.has(name)) continue;
    const file = path.join(SKILLS, name, 'SKILL.md');
    if (!fs.existsSync(file)) continue;
    const text = fs.readFileSync(file, 'utf8');
    const next = withFragment(text, fragment);
    if (next === text) continue;
    drifted.push(name);
    if (!check) fs.writeFileSync(file, next);
  }
  if (check) {
    if (drifted.length) {
      console.error(`skills without the current no-MCP fragment: ${drifted.join(', ')}. ` +
        'Run: node scripts/sync-skill-fallback.mjs');
      return 1;
    }
    console.log('skill fallback in sync.');
    return 0;
  }
  console.log(drifted.length ? `wrote the no-MCP fragment into: ${drifted.join(', ')}` : 'skill fallback in sync.');
  return 0;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  process.exit(main(process.argv.slice(2)));
}
